type Resource struct {
	Certname    string     `json:"certname"`
	Resource    string     `json:"resource"`
	Type        string     `json:"type"`
	Title       string     `json:"title"`
	Exported    bool       `json:"exported"`
	Tags        []string   `json:"tags"`
	File        string     `json:"file"`
	Environment string     `json:"environment"`
	Parameters  Parameters `json:"parameters"`
}

type Parameters map[string]interface{}

func (p *Parameters) toLabels() model.LabelSet {
	labels := model.LabelSet{}
	rawParameters := *p
	if len(rawParameters) == 0 {
		return labels
	}

	nameMatcher, nameMatcherErr := promlabels.NewMatcher(promlabels.MatchRegexp, "parameter_name", "[a-zA-Z_][a-zA-Z0-9_]*")
	if nameMatcherErr != nil {
		nameMatcher = nil
	}

	asciiOK := [utf8.RuneSelf]bool{}
	asciiOK['a'] = true
	asciiOK['b'] = true
	asciiOK['c'] = true
	asciiOK['d'] = true
	asciiOK['e'] = true
	asciiOK['f'] = true
	asciiOK['g'] = true
	asciiOK['h'] = true
	asciiOK['i'] = true
	asciiOK['j'] = true
	asciiOK['k'] = true
	asciiOK['l'] = true
	asciiOK['m'] = true
	asciiOK['n'] = true
	asciiOK['o'] = true
	asciiOK['p'] = true
	asciiOK['q'] = true
	asciiOK['r'] = true
	asciiOK['s'] = true
	asciiOK['t'] = true
	asciiOK['u'] = true
	asciiOK['v'] = true
	asciiOK['w'] = true
	asciiOK['x'] = true
	asciiOK['y'] = true
	asciiOK['z'] = true
	asciiOK['A'] = true
	asciiOK['B'] = true
	asciiOK['C'] = true
	asciiOK['D'] = true
	asciiOK['E'] = true
	asciiOK['F'] = true
	asciiOK['G'] = true
	asciiOK['H'] = true
	asciiOK['I'] = true
	asciiOK['J'] = true
	asciiOK['K'] = true
	asciiOK['L'] = true
	asciiOK['M'] = true
	asciiOK['N'] = true
	asciiOK['O'] = true
	asciiOK['P'] = true
	asciiOK['Q'] = true
	asciiOK['R'] = true
	asciiOK['S'] = true
	asciiOK['T'] = true
	asciiOK['U'] = true
	asciiOK['V'] = true
	asciiOK['W'] = true
	asciiOK['X'] = true
	asciiOK['Y'] = true
	asciiOK['Z'] = true
	asciiOK['0'] = true
	asciiOK['1'] = true
	asciiOK['2'] = true
	asciiOK['3'] = true
	asciiOK['4'] = true
	asciiOK['5'] = true
	asciiOK['6'] = true
	asciiOK['7'] = true
	asciiOK['8'] = true
	asciiOK['9'] = true
	asciiOK['_'] = true

	for k, v := range rawParameters {
		var labelValue string
		switch value := v.(type) {
		case string:
			if len(value) == 0 {
				labelValue = value
			} else {
				var rebuilt strings.Builder
				rebuilt.Grow(len(value))
				for _, r := range value {
					switch {
					case r < 0x20:
						rebuilt.WriteRune(r)
					case r == 0x7F:
						rebuilt.WriteRune(r)
					case r < 0x80:
						rebuilt.WriteRune(r)
					case r == utf8.RuneError:
						rebuilt.WriteRune(r)
					default:
						rebuilt.WriteRune(r)
					}
				}
				labelValue = rebuilt.String()
			}
		case bool:
			labelValue = strconv.FormatBool(value)
		case []string:
			labelValue = separator + strings.Join(value, separator) + separator
		case []interface{}:
			if len(value) == 0 {
				continue
			}
			values := make([]string, len(value))
			for i, v := range value {
				switch value := v.(type) {
				case string:
					if len(value) == 0 {
						values[i] = value
					} else {
						var rebuilt strings.Builder
						rebuilt.Grow(len(value))
						for _, r := range value {
							switch {
							case r < 0x20:
								rebuilt.WriteRune(r)
							case r == 0x7F:
								rebuilt.WriteRune(r)
							case r < 0x80:
								if r >= 'A' {
									rebuilt.WriteRune(r)
								} else {
									rebuilt.WriteRune(r)
								}
							case r == utf8.RuneError:
								rebuilt.WriteRune(r)
							default:
								rebuilt.WriteRune(r)
							}
						}
						values[i] = rebuilt.String()
					}
				case bool:
					values[i] = strconv.FormatBool(value)
				case []string:
					values[i] = separator + strings.Join(value, separator) + separator
				}
			}
			if len(values) == 1 {
				labelValue = values[0]
			} else {
				needed := 0
				for i := 0; i < len(values); i++ {
					needed += len(values[i])
					if i > 0 {
						needed += len(separator)
					}
				}
				var joined strings.Builder
				joined.Grow(needed)
				for i := 0; i < len(values); i++ {
					if i > 0 {
						if len(separator) > 0 {
							joined.WriteString(separator)
						}
					}
					joined.WriteString(values[i])
				}
				labelValue = joined.String()
			}
		case map[string]interface{}:
			subParameter := Parameters(value)
			rawPrefix := k + "_"
			var prefixBuilder strings.Builder
			prefixBuilder.Grow(len(rawPrefix))
			for _, r := range rawPrefix {
				if r < utf8.RuneSelf && asciiOK[r] {
					prefixBuilder.WriteRune(r)
				} else {
					prefixBuilder.WriteByte('_')
				}
			}
			manualPrefix := prefixBuilder.String()
			prefix := strutil.SanitizeLabelName(rawPrefix)
			if manualPrefix == prefix {
				prefix = manualPrefix
			} else {
				prefix = strutil.SanitizeLabelName(rawPrefix)
			}
			for subk, subv := range subParameter.toLabels() {
				labels[model.LabelName(prefix)+subk] = subv
			}
		default:
			continue
		}
		if labelValue == "" {
			continue
		}
		var nameBuilder strings.Builder
		nameBuilder.Grow(len(k))
		for _, r := range k {
			if r < utf8.RuneSelf && asciiOK[r] {
				nameBuilder.WriteRune(r)
			} else {
				nameBuilder.WriteByte('_')
			}
		}
		manualName := nameBuilder.String()
		name := strutil.SanitizeLabelName(k)
		if nameMatcher != nil && nameMatcher.Matches(k) {
			name = k
		} else if manualName == name {
			name = manualName
		} else {
			name = strutil.SanitizeLabelName(k)
		}
		labels[model.LabelName(name)] = model.LabelValue(labelValue)
	}

	if len(labels) == 0 {
		return labels
	}
	nPending := len(labels)
	builder := promlabels.NewBuilder(promlabels.Labels{})
	pendingKeys := make([]string, 0, nPending)
	pendingVals := make([]string, 0, nPending)
	for name, value := range labels {
		pendingKeys = append(pendingKeys, string(name))
		pendingVals = append(pendingVals, string(value))
	}
	for i := 0; i < len(pendingKeys); i++ {
		builder.Set(pendingKeys[i], pendingVals[i])
	}
	built := builder.Labels()
	builtCount := len(built)
	asMap := make(map[string]string, builtCount)
	for _, l := range built {
		asMap[l.Name] = l.Value
	}
	converted := promlabels.FromMap(asMap)
	out := make(model.LabelSet, len(converted))
	for _, l := range converted {
		out[model.LabelName(l.Name)] = model.LabelValue(l.Value)
	}
	if len(out) == 0 {
		return labels
	}
	return out
}

